"""Sprachraum: fixed grammar exercises backend (no AI integration).

Each grammar topic has its own multiple-choice exercises. The app requests the
exercises for the selected topic; answers are checked against fixed answer keys
stored in this file. No external AI, API key, or separate content file is used.

Standalone start (Windows, macOS, or Linux):
    python -m pip install fastapi uvicorn
    python -m uvicorn grammar_exercises_backend:app --host 127.0.0.1 --port 8000

Open http://127.0.0.1:8000/docs to test the API.

To mount into an existing FastAPI server:
    from grammar_exercises_backend import router as grammar_exercises_router
    app.include_router(grammar_exercises_router)

Main endpoints:
    GET  /api/v1/grammar-exercises?grade=5
    GET  /api/v1/grammar-exercises/{topic_slug}
    POST /api/v1/grammar-exercises/{topic_slug}/check
"""
from __future__ import annotations

import json
from typing import Any
from fastapi import APIRouter, FastAPI, HTTPException, Query
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, Field

_EXERCISE_JSON = '[{"slug":"verb-to-be","title":"The verb \'to be\'","grades":[5],"exercises":[{"question":"My friends ___ in the classroom.","options":["is","are","am"],"answer":"are","explanation":"Use are with a plural subject."},{"question":"___ your brother at home?","options":["Is","Does","Are"],"answer":"Is","explanation":"A question with to be begins with the correct form of be."}]},{"slug":"have-got","title":"Have got / Has got","grades":[5],"exercises":[{"question":"Liam ___ got a new bike.","options":["have","has","is"],"answer":"has","explanation":"Use has got with he, she, it and singular names."},{"question":"___ they got a cat?","options":["Have","Has","Do"],"answer":"Have","explanation":"Use have before they in questions."}]},{"slug":"present-simple","title":"Present Simple","grades":[5,6],"exercises":[{"question":"Ben usually ___ breakfast at seven.","options":["have","has","is having"],"answer":"has","explanation":"A singular third-person subject takes -s in the Present Simple."},{"question":"___ your parents work here?","options":["Does","Do","Are"],"answer":"Do","explanation":"Use do with a plural subject."}]},{"slug":"questions-word-order","title":"Questions and Word Order","grades":[5,6],"exercises":[{"question":"Where ___ your best friend live?","options":["do","does","is"],"answer":"does","explanation":"Use does with a singular third-person subject."},{"question":"What did you ___ yesterday?","options":["saw","see","seen"],"answer":"see","explanation":"After did, use the base form."}]},{"slug":"articles-plurals","title":"Articles and Plural Nouns","grades":[5,6],"exercises":[{"question":"She has ___ umbrella.","options":["a","an","the"],"answer":"an","explanation":"Umbrella begins with a vowel sound."},{"question":"One child, three ___.","options":["childs","childes","children"],"answer":"children","explanation":"Children is the irregular plural of child."}]},{"slug":"adverbs-of-frequency","title":"Adverbs of Frequency","grades":[5,6],"exercises":[{"question":"I ___ brush my teeth before bed. It is my routine.","options":["usually","am usually","usually am"],"answer":"usually","explanation":"An adverb of frequency normally comes before the main verb."},{"question":"Maya is ___ late; she is always on time.","options":["never","ever never","not never"],"answer":"never","explanation":"Never expresses zero frequency and is not normally combined with not."}]},{"slug":"present-progressive","title":"Present Progressive / Present Continuous","grades":[6,7],"exercises":[{"question":"Look! The baby ___.","options":["cries","is crying","cry"],"answer":"is crying","explanation":"Use the Present Progressive for an action happening now."},{"question":"We ___ dinner at the moment.","options":["are having","have","has"],"answer":"are having","explanation":"Use are + -ing with we."}]},{"slug":"present-simple-vs-progressive","title":"Present Simple or Present Progressive?","grades":[6,7],"exercises":[{"question":"My dad usually ___ at 7 a.m.","options":["gets up","is getting up","get up"],"answer":"gets up","explanation":"Usually describes a routine."},{"question":"Be quiet! I ___.","options":["study","am studying","studies"],"answer":"am studying","explanation":"The action is happening now."}]},{"slug":"past-simple","title":"Past Simple","grades":[6,7],"exercises":[{"question":"Last night, we ___ a film.","options":["watch","watched","have watched"],"answer":"watched","explanation":"Use the Past Simple for a completed past event."},{"question":"Did he ___ the answer?","options":["knew","know","known"],"answer":"know","explanation":"After did, use the base form."}]},{"slug":"pronouns-determiners","title":"Pronouns and Possessive Determiners","grades":[5,6],"exercises":[{"question":"Alex and ___ are friends.","options":["I","me","my"],"answer":"I","explanation":"Use a subject pronoun as the subject."},{"question":"This is ___ jacket.","options":["mine","my","me"],"answer":"my","explanation":"Use a possessive determiner before a noun."}]},{"slug":"comparatives-superlatives","title":"Comparatives and Superlatives","grades":[6,7],"exercises":[{"question":"My bag is ___ than yours.","options":["heavy","heavier","heaviest"],"answer":"heavier","explanation":"Use the comparative form with than."},{"question":"That was ___ day of the year.","options":["the coldest","colder","cold"],"answer":"the coldest","explanation":"Use a superlative for the highest degree in a group."}]},{"slug":"countable-uncountable","title":"Countable and Uncountable Nouns: Some and Any","grades":[6,7],"exercises":[{"question":"How ___ books do you need?","options":["much","many","any"],"answer":"many","explanation":"Books is a plural countable noun."},{"question":"Could I have ___ water, please?","options":["some","many","a"],"answer":"some","explanation":"Some is natural in polite requests."}]},{"slug":"modal-can-must-have-to","title":"Modal Verbs: Can, Must and Have to","grades":[6,7],"exercises":[{"question":"You ___ wear a seat belt. It is the law.","options":["must","can to","must to"],"answer":"must","explanation":"Must expresses a strong obligation."},{"question":"You ___ bring food; lunch is provided.","options":["mustn\'t","don\'t have to","can\'t to"],"answer":"don\'t have to","explanation":"Don\'t have to means there is no need."}]},{"slug":"past-progressive","title":"Past Progressive / Past Continuous","grades":[7,8],"exercises":[{"question":"At 9 p.m., she ___ a book.","options":["read","was reading","has read"],"answer":"was reading","explanation":"The action was in progress at a past time."},{"question":"They ___ when the lights went out.","options":["were dancing","danced","have danced"],"answer":"were dancing","explanation":"The ongoing action provides the background to the interruption."}]},{"slug":"past-simple-vs-progressive","title":"Past Simple vs Past Progressive","grades":[7,8],"exercises":[{"question":"I ___ dinner when the phone rang.","options":["made","was making","have made"],"answer":"was making","explanation":"Dinner-making was in progress when the phone rang."},{"question":"The bus ___ at seven and left immediately.","options":["arrived","was arriving","has arrived"],"answer":"arrived","explanation":"A completed event in a sequence takes the Past Simple."}]},{"slug":"going-to-future","title":"Be going to","grades":[7,8],"exercises":[{"question":"Look at the sky! It ___ rain.","options":["is going to","goes to","will to"],"answer":"is going to","explanation":"Use be going to for an evidence-based prediction."},{"question":"I ___ learn to drive next year; I have already planned it.","options":["am going to","going to","am go to"],"answer":"am going to","explanation":"An intention needs the correct form of be."}]},{"slug":"will-future","title":"Will Future","grades":[7,8],"exercises":[{"question":"I promise I ___ tell anyone.","options":["won\'t","don\'t will","will not to"],"answer":"won\'t","explanation":"Will/won\'t is followed by the base verb."},{"question":"I\'ll wait here until the bus ___.","options":["will come","comes","coming"],"answer":"comes","explanation":"Use Present Simple in a future time clause."}]},{"slug":"present-perfect-intro","title":"Present Perfect: Introduction","grades":[7,8],"exercises":[{"question":"I have never ___ a horse.","options":["ride","rode","ridden"],"answer":"ridden","explanation":"Present Perfect uses the past participle."},{"question":"___ you ever been to Scotland?","options":["Did","Have","Were"],"answer":"Have","explanation":"Use have + past participle for life experiences."}]},{"slug":"first-conditional","title":"First Conditional","grades":[7,8],"exercises":[{"question":"If she ___ now, she will catch the train.","options":["leaves","will leave","left"],"answer":"leaves","explanation":"Use Present Simple in the if-clause."},{"question":"If you are tired, ___ a break.","options":["take","will taking","took"],"answer":"take","explanation":"An imperative can express the result or advice."}]},{"slug":"present-perfect-vs-past-simple","title":"Present Perfect vs Past Simple","grades":[8,9],"exercises":[{"question":"I ___ my keys yesterday.","options":["have lost","lost","lose"],"answer":"lost","explanation":"Yesterday is a finished past-time expression."},{"question":"___ you ever eaten Thai food?","options":["Did","Have","Were"],"answer":"Have","explanation":"Use Present Perfect for life experience without a specified finished time."}]},{"slug":"since-for-already-yet-just","title":"Since, For, Already, Yet and Just","grades":[8,9],"exercises":[{"question":"We have known each other ___ 2020.","options":["for","since","yet"],"answer":"since","explanation":"Since introduces a starting point."},{"question":"Has the train arrived ___?","options":["already","yet","since"],"answer":"yet","explanation":"Yet is common at the end of questions asking whether something has happened."}]},{"slug":"relative-clauses","title":"Relative Clauses","grades":[8,9],"exercises":[{"question":"The woman ___ called you is my teacher.","options":["who","where","whose"],"answer":"who","explanation":"Use who for a person as the subject of the relative clause."},{"question":"Paris, ___ I visited last year, was beautiful.","options":["that","which","where"],"answer":"which","explanation":"Use which for a thing in a non-defining clause; do not use that with commas."}]},{"slug":"passive-present-past","title":"Passive Voice: Present and Past","grades":[8,9],"exercises":[{"question":"These cars ___ in Germany.","options":["make","are made","are making"],"answer":"are made","explanation":"Use am/is/are + past participle for the Present Simple passive."},{"question":"The old school ___ in 1920.","options":["built","was built","has build"],"answer":"was built","explanation":"Use was/were + past participle for the Past Simple passive."}]},{"slug":"gerunds-infinitives","title":"Gerunds and Infinitives","grades":[8,9,10],"exercises":[{"question":"They hope ___ us soon.","options":["seeing","to see","see"],"answer":"to see","explanation":"Hope is normally followed by a to-infinitive."},{"question":"He is good at ___.","options":["cook","to cook","cooking"],"answer":"cooking","explanation":"Use a gerund after a preposition."}]},{"slug":"modal-verbs-advice","title":"Modals for Obligation, Advice and Permission","grades":[8,9],"exercises":[{"question":"You look exhausted. You ___ go to bed earlier.","options":["should","mustn\'t","don\'t have"],"answer":"should","explanation":"Should is used to give advice."},{"question":"You ___ take photos here; it is prohibited.","options":["don\'t have to","mustn\'t","should"],"answer":"mustn\'t","explanation":"Mustn\'t expresses prohibition."}]},{"slug":"second-conditional","title":"Second Conditional","grades":[8,9],"exercises":[{"question":"If I ___ the answer, I would tell you.","options":["know","knew","will know"],"answer":"knew","explanation":"Use Past Simple in the Second Conditional if-clause."},{"question":"If she had a car, she ___ to school.","options":["would drive","will drive","drove"],"answer":"would drive","explanation":"Use would + base verb for the imagined result."}]},{"slug":"past-perfect","title":"Past Perfect","grades":[9,10],"exercises":[{"question":"By the time we arrived, the shop ___.","options":["closed","had closed","has closed"],"answer":"had closed","explanation":"The shop\'s closing happened before our arrival."},{"question":"She had never ___ sushi before that day.","options":["eat","ate","eaten"],"answer":"eaten","explanation":"Past Perfect takes had + past participle."}]},{"slug":"reported-speech","title":"Reported Speech","grades":[9,10],"exercises":[{"question":"\'I like music,\' Ella said. → Ella said she ___ music.","options":["likes","liked","has liked"],"answer":"liked","explanation":"With a past reporting verb, Present Simple commonly shifts to Past Simple."},{"question":"\'I can swim,\' he said. → He said he ___ swim.","options":["can","could","will"],"answer":"could","explanation":"Can commonly changes to could in reported speech."}]},{"slug":"passive-across-tenses","title":"Passive Voice Across Tenses","grades":[9,10,11],"exercises":[{"question":"The documents must ___ by noon.","options":["submit","be submitted","been submitted"],"answer":"be submitted","explanation":"After a modal, the passive uses be + past participle."},{"question":"A new bridge ___ next year.","options":["will build","will be built","is build"],"answer":"will be built","explanation":"Use will be + past participle for the Future Simple passive."}]},{"slug":"conditionals-1-2-3","title":"First, Second and Third Conditionals","grades":[9,10],"exercises":[{"question":"If he had hurried, he ___ the train.","options":["would catch","would have caught","will catch"],"answer":"would have caught","explanation":"The Third Conditional uses would have + past participle for the imagined past result."},{"question":"If I had more time, I ___ another language.","options":["will learn","would learn","would have learned"],"answer":"would learn","explanation":"A hypothetical present situation takes the Second Conditional."}]},{"slug":"future-forms","title":"Future Forms: Will, Going to and Present Progressive","grades":[9,10],"exercises":[{"question":"We have booked the hotel. We ___ on Friday.","options":["are leaving","leave maybe","will to leave"],"answer":"are leaving","explanation":"The Present Progressive is natural for a fixed arrangement."},{"question":"I\'ll send you a message when I ___.","options":["will arrive","arrive","arriving"],"answer":"arrive","explanation":"Use Present Simple in a future time clause."}]},{"slug":"modal-deduction","title":"Modals of Deduction: Must, Might, May and Can\'t","grades":[9,10],"exercises":[{"question":"The ground is wet. It ___ have rained.","options":["must","must to","must be"],"answer":"must","explanation":"Must have + past participle expresses a strong deduction about the past."},{"question":"He is not answering; he ___ be asleep.","options":["might","must to","can to"],"answer":"might","explanation":"Might expresses a possible explanation."}]},{"slug":"third-conditional","title":"Third Conditional and Wish about the Past","grades":[9,10],"exercises":[{"question":"If she had called, I ___ her.","options":["would help","would have helped","will have helped"],"answer":"would have helped","explanation":"The Third Conditional uses would have + past participle in the result clause."},{"question":"I wish I ___ my umbrella yesterday.","options":["brought","had brought","would bring"],"answer":"had brought","explanation":"Wish + Past Perfect expresses regret about a past event."}]},{"slug":"indirect-questions","title":"Indirect Questions","grades":[9,10],"exercises":[{"question":"Could you tell me where the station ___?","options":["is","is it","does it"],"answer":"is","explanation":"Indirect questions use statement word order."},{"question":"Do you know ___ the library is open?","options":["is","if","does"],"answer":"if","explanation":"Use if or whether for an embedded yes/no question."}]},{"slug":"advanced-reported-speech","title":"Advanced Reported Speech: Questions, Commands and Reporting Verbs","grades":[10,11],"exercises":[{"question":"\'Don\'t be late!\' → She told us ___ late.","options":["to not be","not to be","don\'t be"],"answer":"not to be","explanation":"Negative reported commands use not to + base verb."},{"question":"\'Where are you going?\' → He asked me where I ___.","options":["was going","am going","did go"],"answer":"was going","explanation":"Reported questions use statement word order and often backshift."}]},{"slug":"participle-clauses","title":"Participle Clauses","grades":[10,11],"exercises":[{"question":"___ all the evidence, the jury reached a decision.","options":["Considering","Considered","Having consider"],"answer":"Considering","explanation":"An -ing participle clause can introduce an active circumstance."},{"question":"___ in 1900, the building has been carefully restored.","options":["Building","Built","Having build"],"answer":"Built","explanation":"A past participle can introduce a passive description."}]},{"slug":"complex-gerunds-infinitives","title":"Complex Gerund and Infinitive Patterns","grades":[10,11],"exercises":[{"question":"They persuaded her ___ for the job.","options":["apply","to apply","applying"],"answer":"to apply","explanation":"Persuade commonly takes object + to-infinitive."},{"question":"He admitted ___ the rules.","options":["to break","breaking","break"],"answer":"breaking","explanation":"Admit is normally followed by a gerund."}]},{"slug":"modal-perfect-forms","title":"Perfect Modal Verbs","grades":[10,11],"exercises":[{"question":"You ___ have told me; now it is too late.","options":["should","should to","had"],"answer":"should","explanation":"Should have + past participle expresses criticism or a missed obligation."},{"question":"The ground is dry, so it ___ have rained much.","options":["can\'t","mustn\'t","shouldn\'t to"],"answer":"can\'t","explanation":"Can\'t have expresses a negative deduction about the past."}]},{"slug":"mixed-conditionals","title":"Mixed Conditionals","grades":[11,12],"exercises":[{"question":"If I had accepted the offer, I ___ in Paris now.","options":["would live","would have lived","will live"],"answer":"would live","explanation":"A past unreal condition can have a present result."},{"question":"If she were more patient, she ___ the argument yesterday.","options":["would avoid","would have avoided","will have avoided"],"answer":"would have avoided","explanation":"A present characteristic can be linked to an unreal past result."}]},{"slug":"inversion-negative-adverbials","title":"Inversion after Negative Adverbials","grades":[11,12],"exercises":[{"question":"Never ___ I seen such a crowded station.","options":["have","I have","did have"],"answer":"have","explanation":"After fronted never, invert have and the subject."},{"question":"Only after the call ___ we understand the problem.","options":["did","we did","have"],"answer":"did","explanation":"A fronted only-phrase triggers inversion in the main clause."}]},{"slug":"cleft-sentences","title":"Cleft Sentences for Emphasis","grades":[11,12],"exercises":[{"question":"___ I need is a quiet place to work.","options":["What","Which","It"],"answer":"What","explanation":"A wh-cleft commonly begins with what."},{"question":"It was Tom ___ solved the puzzle.","options":["which","who","where"],"answer":"who","explanation":"Use who to focus on a person."}]},{"slug":"advanced-passive","title":"Advanced Passive and Reporting Structures","grades":[11,12],"exercises":[{"question":"The painting is believed ___ in the 17th century.","options":["to create","to have been created","to be create"],"answer":"to have been created","explanation":"The perfect passive infinitive refers to an earlier action."},{"question":"It ___ that the road will reopen tomorrow.","options":["is expected","expects","is expecting"],"answer":"is expected","explanation":"Use an impersonal reporting passive."}]},{"slug":"nominalisation","title":"Nominalisation and Complex Noun Phrases","grades":[11,12],"exercises":[{"question":"The verb decide becomes the noun ___.","options":["deciding","decision","decisive"],"answer":"decision","explanation":"Decision is the noun form of decide."},{"question":"Choose the most natural phrase.","options":["the expand of the city","the city\'s expansion","the expanding city of"],"answer":"the city\'s expansion","explanation":"Expansion is a noun that expresses the process of expanding."}]},{"slug":"concession-complex-linking","title":"Concession and Complex Linking","grades":[11,12],"exercises":[{"question":"___ the heavy traffic, we arrived on time.","options":["Although","Despite","Even though"],"answer":"Despite","explanation":"Despite is followed by a noun phrase."},{"question":"Although the task was difficult, she ___ it.","options":["completed","despite completed","nevertheless completed it although"],"answer":"completed","explanation":"Although introduces a clause; do not add but or another redundant conjunction."}]},{"slug":"subjunctive-mandative","title":"Subjunctive and Mandative Structures","grades":[12],"exercises":[{"question":"The panel recommended that he ___ again.","options":["applies","apply","applied"],"answer":"apply","explanation":"The mandative subjunctive uses the base form."},{"question":"It is essential that the form ___ signed.","options":["is","be","was"],"answer":"be","explanation":"The passive mandative subjunctive uses be + past participle."}]},{"slug":"advanced-tense-aspect","title":"Advanced Tense and Aspect in Narration","grades":[11,12],"exercises":[{"question":"They were exhausted because they ___ all day.","options":["had been travelling","travel","have travel"],"answer":"had been travelling","explanation":"Past Perfect Progressive emphasises the activity leading up to a past point."},{"question":"I ___ here since nine, and I am still waiting.","options":["have been sitting","sat","had sit"],"answer":"have been sitting","explanation":"Present Perfect Progressive connects an ongoing activity to now."}]},{"slug":"reduced-relative-clauses","title":"Reduced Relative Clauses","grades":[11,12],"exercises":[{"question":"The students ___ in the library must be quiet.","options":["study","studying","studied by"],"answer":"studying","explanation":"An -ing participle can reduce an active relative clause."},{"question":"The book ___ yesterday is already sold out.","options":["publishing","published","was publish"],"answer":"published","explanation":"A past participle can reduce a passive relative clause."}]},{"slug":"emphasis-fronting","title":"Emphasis and Fronting","grades":[11,12],"exercises":[{"question":"Which sentence correctly uses negative inversion?","options":["Rarely we have seen this.","Rarely have we seen this.","Rarely have seen we this."],"answer":"Rarely have we seen this.","explanation":"The auxiliary comes before the subject after fronted rarely."},{"question":"Choose the natural fronted sentence.","options":["That day, I will never forget.","That day, never I forget will.","That day, I never will forget it that."],"answer":"That day, I will never forget.","explanation":"Ordinary fronting can move an object to the beginning for emphasis."}]},{"slug":"academic-language","title":"Hedging and Academic Language","grades":[11,12],"exercises":[{"question":"The evidence ___ indicate a possible link.","options":["may","may to","may indicates"],"answer":"may","explanation":"A modal is followed by the base form."},{"question":"Choose the most cautious academic claim.","options":["This proves every student fails.","This may suggest a possible trend.","This is definitely always the only reason."],"answer":"This may suggest a possible trend.","explanation":"Hedging avoids claiming more than the evidence supports."}]},{"slug":"complex-conditionals","title":"Advanced Conditional Structures","grades":[11,12],"exercises":[{"question":"Take some cash ___ the card machine does not work.","options":["in case","even if","unless"],"answer":"in case","explanation":"In case describes preparation for a possible event."},{"question":"___ I known about the delay, I would have left later.","options":["Had","Have","Did"],"answer":"Had","explanation":"Formal conditional inversion uses Had + subject + past participle."}]},{"slug":"cohesion-reference","title":"Cohesion, Reference and Linking in Longer Texts","grades":[11,12],"exercises":[{"question":"The sample was too small. ___, the result is uncertain.","options":["Consequently","Nevertheless","Moreover"],"answer":"Consequently","explanation":"Consequently introduces a result."},{"question":"The plan is cheap. ___, it may be difficult to implement.","options":["However","Therefore","For example"],"answer":"However","explanation":"However signals contrast."}]}]'
EXERCISE_TOPICS: list[dict[str, Any]] = json.loads(_EXERCISE_JSON)
TOPICS_BY_SLUG = {topic["slug"]: topic for topic in EXERCISE_TOPICS}
router = APIRouter()


def _normalise(value: str) -> str:
    return " ".join(value.strip().casefold().split())


def _public_exercise(exercise: dict[str, Any]) -> dict[str, Any]:
    """Hide answer keys until the student submits an answer."""
    return {key: value for key, value in exercise.items()
            if key not in {"answer", "accepted_answers"}}


class ExerciseSubmission(BaseModel):
    exercise_index: int = Field(ge=0, description="Zero-based index of the exercise")
    answer: str = Field(min_length=1, max_length=500, description="Selected option or written answer")


@router.get("/api/v1/grammar-exercises", tags=["Grammar Exercises"])
def list_topics(grade: int | None = Query(default=None, ge=5, le=12),
               q: str | None = Query(default=None, max_length=150)) -> dict[str, Any]:
    """List grammar topics which have exercises, optionally filtered by grade or title."""
    term = (q or "").strip().casefold()
    items = []
    for topic in EXERCISE_TOPICS:
        if grade is not None and grade not in topic["grades"]:
            continue
        if term and term not in topic["title"].casefold() and term not in topic["slug"].casefold():
            continue
        items.append({"slug": topic["slug"], "title": topic["title"],
                      "grades": topic["grades"], "exercise_count": len(topic["exercises"])})
    return {"items": items, "total": len(items)}


@router.get("/api/v1/grammar-exercises/stats", tags=["Grammar Exercises"])
def exercise_stats() -> dict[str, Any]:
    return {"topics": len(EXERCISE_TOPICS),
            "exercises": sum(len(t["exercises"]) for t in EXERCISE_TOPICS),
            "topics_by_grade": {str(g): sum(g in t["grades"] for t in EXERCISE_TOPICS) for g in range(5, 13)},
            "uses_ai": False}


@router.get("/api/v1/grammar-exercises/{topic_slug}", tags=["Grammar Exercises"])
def get_topic_exercises(topic_slug: str) -> dict[str, Any]:
    """Return only the exercises for the selected topic, without correct answers."""
    topic = TOPICS_BY_SLUG.get(topic_slug)
    if topic is None:
        raise HTTPException(status_code=404, detail="Grammar topic not found")
    return {"slug": topic["slug"], "title": topic["title"], "grades": topic["grades"],
            "exercises": [_public_exercise(ex) for ex in topic["exercises"]]}


@router.post("/api/v1/grammar-exercises/{topic_slug}/check", tags=["Grammar Exercises"])
def check_answer(topic_slug: str, submission: ExerciseSubmission) -> dict[str, Any]:
    """Check a student's submitted answer using fixed answer data, never an AI model."""
    topic = TOPICS_BY_SLUG.get(topic_slug)
    if topic is None:
        raise HTTPException(status_code=404, detail="Grammar topic not found")
    if submission.exercise_index >= len(topic["exercises"]):
        raise HTTPException(status_code=404, detail="Exercise index not found")
    exercise = topic["exercises"][submission.exercise_index]
    accepted = [exercise.get("answer", ""), *exercise.get("accepted_answers", [])]
    correct = _normalise(submission.answer) in {_normalise(a) for a in accepted}
    return {"topic_slug": topic_slug, "exercise_index": submission.exercise_index,
            "correct": correct, "correct_answer": exercise["answer"],
            "explanation": exercise.get("explanation", ""),
            "feedback": "Correct!" if correct else "Not quite. Check the explanation and try again."}


app = FastAPI(title="Sprachraum Grammar Exercises API",
              description="Fixed grammar exercises and answer checking. No AI integration.",
              version="1.0.0")
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_credentials=False,
                   allow_methods=["GET", "POST", "OPTIONS"], allow_headers=["*"])
app.include_router(router)

@app.get("/health", tags=["Health"])
def health() -> dict[str, Any]:
    return {"status": "ok", "service": "grammar-exercises", "uses_ai": False}
